def predict(probe):
    # Beliefs about the mechanism:
    # - Empty string returns "z" (special case) [E6]
    # - First character: if letter, shift up by 1 with wrap (z->a, Z->A);
    #   non-letters unchanged [E1,E2,E3,E5,E6,E7,E9,E10,E11,E12]
    # - Append "y" to the end unless the ORIGINAL input already ends in "y"
    #   [E4,E6,E10,E12 (no append) vs E1,E2,E3,E5,E7,E8,E9,E11 (append)]
    def transform(s):
        if s == "":
            return "z"
        c = s[0]
        if 'a' <= c <= 'z':
            c = chr((ord(c) - ord('a') + 1) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            c = chr((ord(c) - ord('A') + 1) % 26 + ord('A'))
        result = c + s[1:]
        if not s.endswith('y'):
            result += 'y'
        return result

    return {"outputs": [transform(x) for x in probe["inputs"]]}
